#!/usr/bin/env bash
# Date de naissance d'un mineur, 1/3 — backend (avec MIGRATION 20261222000000_birth_date_request).
# - Table BirthDateRequest : le mineur demande à son parent (lien personnel, 7 jours, usage unique) de
#   renseigner, corriger ou effacer sa date de naissance ;
# - une date de majeur, saisie par le parent (ici ou sur la page de l'autorisation), doit être confirmée ;
#   confirmée, le membre passe majeur (makeAdult : coordonnées du parent effacées, demandes supprimées,
#   e-mail au jeune) ;
# - admin : user.markAdultWithProof (« Passer majeur (justificatif vu) »), sans date.
# Prérequis : apply-pdf-case-mineur.sh.
# Usage (racine du repo) : bash apply-date-naissance-1-backend.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"prisma/schema.prisma" 2>/dev/null | grep -qF "model BirthDateRequest"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "drawOnlineFooters" "packages/backend/src/modules/imageConsent/consentPdf.service.ts" 2>/dev/null || { echo "lancez d'abord apply-pdf-case-mineur.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/legal/consentement-en-ligne.mdx" "apps/web/src/features/docs/entities/procedureMap.generated.json" "e2e/droit-a-l-image-parent.spec.ts" "packages/backend/src/email/templates/comingOfAge.ts" "packages/backend/src/modules/imageConsent/imageConsentGuardian.service.ts" "packages/backend/src/modules/imageConsent/router.ts" "packages/backend/src/modules/privacy/retention.service.ts" "packages/backend/src/modules/users/comingOfAge.service.ts" "packages/backend/src/modules/users/router.ts" "packages/contracts/src/legal/imageConsent.ts" "prisma/schema.prisma")
CREATED=("packages/backend/src/email/templates/birthDateRequest.ts" "packages/backend/src/modules/users/birthDateRequest.service.ts" "prisma/migrations/20261222000000_birth_date_request/migration.sql")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "prisma/migrations/20261222000000_birth_date_request" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "model BirthDateRequest" "prisma/schema.prisma" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "packages/backend/src/email/templates"
base64 -d > "packages/backend/src/email/templates/birthDateRequest.ts" <<'B64'
